INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT146-S3-Q3$batch13$, 146, 3, 3, $batch13$Most Strongly Supported$batch13$, $batch13$Sales manager: Having spent my entire career in sales, most of that time as a sales manager for a large computer company, I know that natural superstar salespeople are rare. But many salespeople can perform like superstars if they have a good manager. Therefore, companies should _______.$batch13$, $batch13$Which one of the following most logically completes the sales manager’s argument?$batch13$, $batch13$B$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=146 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT146-S3-Q3$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$devote more effort to training than to evaluating salespeople$batch13$, $batch13$Unsupported$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT146-S3-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$devote more effort to finding good managers than to finding natural superstar salespeople$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT146-S3-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$keep to a minimum the number of salespeople for which a manager is responsible$batch13$, $batch13$Unsupported$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT146-S3-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$promote more natural superstar salespeople to management positions$batch13$, $batch13$Unsupported$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT146-S3-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$reward superstar performance more than superstar talent$batch13$, $batch13$Unsupported$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT146-S3-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT146-S3-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Statements$batch13$, $batch13$Natural superstar salespeople are rare. Many salespeople can perform like superstars if they have a good manager.$batch13$), (1, $batch13$Evaluate$batch13$, $batch13$The blank follows "Therefore, companies should". Superstars are hard to find, but good managers can produce superstar results. So the effort belongs in finding good managers.$batch13$), (2, $batch13$Goal$batch13$, $batch13$Companies should focus on finding good managers rather than natural superstars.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT146-S3-Q3$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$The argument is about managers, not training versus evaluation.$batch13$), ($batch13$B$batch13$, $batch13$Superstars are rare and good managers make ordinary salespeople perform like them. So looking for good managers pays off more.$batch13$), ($batch13$C$batch13$, $batch13$How many salespeople a manager handles never comes up.$batch13$), ($batch13$D$batch13$, $batch13$Nothing says superstar salespeople make good managers.$batch13$), ($batch13$E$batch13$, $batch13$Rewards aren't discussed. The argument is about managers.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT146-S3-Q3$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
